import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"韦讽录事宅观曹将军画马","description":"","frontmatter":{"title":"韦讽录事宅观曹将军画马","date":"2026-11-23T00:00:00.000Z","seq":19,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"杜甫","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/韦讽录事宅观曹将军画马.md","filePath":"blogs/唐诗三百首·七言古诗/韦讽录事宅观曹将军画马.md"}'),o={name:"blogs/唐诗三百首·七言古诗/韦讽录事宅观曹将军画马.md"};function l(c,a,n,_,m,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="韦讽录事宅观曹将军画马" tabindex="-1">韦讽录事宅观曹将军画马 <a class="header-anchor" href="#韦讽录事宅观曹将军画马" aria-label="Permalink to &quot;韦讽录事宅观曹将军画马&quot;">​</a></h1><p class="poem-meta">唐 · 杜甫　·　七言古诗</p><div class="poem"><p class="poem-stanza">国初已来画鞍马，神妙独数江都王。</p><p class="poem-stanza">将军得名三十载，人间又见真乘黄。</p><p class="poem-stanza">曾貌先帝照夜白，龙池十日飞霹雳。</p><p class="poem-stanza">内府殷红玛瑙盘，婕妤传诏才人索。</p><p class="poem-stanza">盘赐将军拜舞归，轻纨细绮相追飞。</p><p class="poem-stanza">贵戚权门得笔迹，始觉屏障生光辉。</p><p class="poem-stanza">昔日太宗拳毛䯄，近时郭家狮子花。</p><p class="poem-stanza">今之新图有二马，复令识者久叹嗟。</p><p class="poem-stanza">此皆骑战一敌万，缟素漠漠开风沙。</p><p class="poem-stanza">其余七匹亦殊绝，迥若寒空动烟雪。</p><p class="poem-stanza">霜蹄蹴踏长楸间，马官厮养森成列。</p><p class="poem-stanza">可怜九马争神骏，顾视清高气深稳。</p><p class="poem-stanza">借问苦心爱者谁，后有韦讽前支遁。</p><p class="poem-stanza">忆昔巡幸新丰宫，翠华拂天来向东。</p><p class="poem-stanza">腾骧磊落三万匹，皆与此图筋骨同。</p><p class="poem-stanza">自从献宝朝河宗，无复射蛟江水中。</p><p class="poem-stanza">君不见金粟堆前松柏里，龙媒去尽鸟呼风。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
